 * agent-g run 165 (docs/IDO_CODEGEN.md kit CV): rewritten from the cfe-shaped PKT macro body (93.54) as
 * real C++ -- every append is the gfx context's inline Ctx::next() (n read, n + 1 stored, &buf[n]), and the
 * stock 2.0I gbi.h gSPTexture / gSPScisTextureRectangle macros get `CTX->next()` as their pkt argument, so
 * the macro's two gImmp1 re-evaluations of pkt ARE the RDPHALF_1 / RDPHALF_2 appends. No pads. 95.36
 * standalone. LEFT: as 329C / 2DE0, the edg pool variable is callee-saved in the target.
 * run 172 (kit CXVII): eight function-top volatile scalars give the target frame 96 (was 64; the named
 * homes sit at the frame bottom as in the target): 95.36 -> 95.41.
 * run 189 (kit CLVII): the rectangle's three appends spelled separately (pkt / pkt2 / pkt3 in the
 * macro): rect as `n + 1`, RDPHALF_1 as `n = dl->n; dl->n++`, RDPHALF_2 as `n = dl->n++`. Same as 329C.
 * agent-c run 268 (kit CCCXII): the gSPTexture append alone in its own basic block (`if (arg4) {}` before it,
 * `if (1) {}` after it): in the entry block (incoming a0-a3 precoloured) or the loader-call block (a1 argument) the
 * shared ctx / MAX pool var could not take a1; isolated it gets the target's a1 everywhere (98.33 -> 98.18 before
 * re-tuning), then a hill-climb over code-free tests / per-pkt accessors (rect pkts me(me())->nD() / me(me())->nR1()
 * / me()->nD(), `if (arg3) {}` after the loader, plain `w = arg4`): -> 98.95. */
typedef float f32; typedef int s32; typedef unsigned int u32; typedef short s16;
extern "C" { extern char D_00000000; extern int gui_func_00000000(...); }
#define _SHIFTL(v, s, w) ((unsigned int) (((unsigned int)(v) & ((0x01 << (w)) - 1)) << (s)))
#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))
struct Gwords { unsigned int w0, w1; };
union Gfx { Gwords words; long long force_structure_alignment; };
#define G_TEXTURE 0xbb
#define G_TEXRECT 0xe4
#define G_RDPHALF_1 0xb4
#define G_RDPHALF_2 0xb3
#define gImmp1(pkt, c, p0) { Gfx *_g = (Gfx *)(pkt); _g->words.w0 = _SHIFTL((c), 24, 8); _g->words.w1 = (unsigned int)(p0); }
#define gSPTexture(pkt, s, t, level, tile, on) \
{ Gfx *_g = (Gfx *)(pkt); \
	_g->words.w0 = (_SHIFTL(G_TEXTURE, 24, 8) | _SHIFTL(0, 16, 8) | _SHIFTL(level, 11, 3) | _SHIFTL(tile, 8, 3) | _SHIFTL(on, 0, 8)); \
	_g->words.w1 = (_SHIFTL(s, 16, 16) | _SHIFTL(t, 0, 16)); }
#define gSPScisTextureRectangle(pkt, pkt2, pkt3, xl, yl, xh, yh, tile, s, t, dsdx, dtdy) \
{ Gfx *_g = (Gfx *)(pkt); \
    _g->words.w0 = (_SHIFTL(G_TEXRECT, 24, 8) | _SHIFTL(MAX((s16)(xh),0), 12, 12) | _SHIFTL(MAX((s16)(yh),0), 0, 12)); \
    _g->words.w1 = (_SHIFTL((tile), 24, 3) | _SHIFTL(MAX((s16)(xl),0), 12, 12) | _SHIFTL(MAX((s16)(yl),0), 0, 12)); \
    gImmp1(pkt2, G_RDPHALF_1, (_SHIFTL(((s) - (((s16)(xl) < 0) ? (((s16)(dsdx) < 0) ? (MAX((((s16)(xl)*(s16)(dsdx))>>7),0)) : (MIN((((s16)(xl)*(s16)(dsdx))>>7),0))) : 0)), 16, 16) | \
                 _SHIFTL(((t) - (((yl) < 0) ? (((s16)(dtdy) < 0) ? (MAX((((s16)(yl)*(s16)(dtdy))>>7),0)) : (MIN((((s16)(yl)*(s16)(dtdy))>>7),0))) : 0)), 0, 16))); \
    gImmp1(pkt3 + 0, G_RDPHALF_2,(_SHIFTL((dsdx), 16, 16) | _SHIFTL((dtdy), 0, 16))); }
template <class T> inline T *me(T *p) { return p; } /* agent-c run 252: zero-code accessor (kit CCLXXXIV) */
struct DL { Gfx *buf; int n; };
struct Ctx { char pad[0xC]; DL *dl; Gfx *next() { int n = dl->n; dl->n = n + 1; return &dl->buf[n]; }
    Gfx *nextb() { int n = dl->n; dl->n = n + 1; return &dl->buf[n]; } Gfx *nC() { int n; n = dl->n; dl->n++; return &dl->buf[n]; } Gfx *nD() { int n = dl->n++; return &dl->buf[n]; }
    /* agent-c run 255: the result through a named inline local (the 46050 nextr() lever) on the RDPHALF_2 append: 97.94 -> 98.19;
     * then a pair grid over (rect pkt, RDPHALF_2 pkt): rect `me(me(CTX))->nR1()`, RDPHALF_2 `me(CTX)->nC()`: -> 98.25 */
    Gfx *nR1() { Gfx *r = &dl->buf[dl->n++]; return r; } };
#define CTX (*(Ctx **)&D_00000000)
struct Spr { char p8[8]; int tex; char pc[0x20 - 0xC]; s16 w; s16 h; int fmt; };
struct Obj { char p[0x10]; Spr *spr; };
/* agent-g run 299 (kit CCCLXXIV source-line lever): the signature, the declarations and the `if (arg4) {}` split on ONE
 * line -- the entry block's arg1 home store (sw a1,100(sp)) now shares the first statement's line, so as1 issues the
 * CTX address addiu before it like the target (99.141 -> 99.922; signature x declaration x first-test joins, 24) */
extern "C" void gui_func_00003714(Obj *arg0, s32 arg1, s32 arg2, s32 arg3, s32 arg4, f32 arg5, f32 arg6) { volatile s32 q0, q1, q2, q3, q4, q5, q6, q7; s32 x, y; s32 w, h; f32 fw, fh; Spr *spr; if (arg4) {} /* agent-c run 268: BB split -- the texture append in a block of its own (ctx a1 as the target) */
    /* agent-c run 252: per-pkt accessor greedy (kit CCLXXXIV): 97.41 -> 97.94. agent-c run 269 (kit CCCXIV): the gSPTexture
     * macro written out with the BB split BETWEEN the packet allocation and its two stores (and none before spr): the alloc
     * block keeps the ctx on a1, while _g now also lives in the loader-call block, where the call's argument registers are
     * forbidden -> _g t0 as in the target (98.95 -> 99.00; the two word stores must share one source line) */
    { Gfx *_g = me(me(CTX))->nD(); if (1) {}
      _g->words.w0 = (_SHIFTL(G_TEXTURE, 24, 8) | _SHIFTL(0, 16, 8) | _SHIFTL(0, 11, 3) | _SHIFTL(0, 8, 3) | _SHIFTL(1, 0, 8)); _g->words.w1 = (_SHIFTL(0x8000, 16, 16) | _SHIFTL(0x8000, 0, 16)); }
    spr = arg0->spr;
    h = spr->h + 0 * (int)(spr->w); /* agent-g run 210: folded counted use (zero-use sweep): 96.51 -> 97.27 */
    gui_func_00000000(CTX, spr->tex, spr->w, h, arg3, 0, arg4, h, 0); /* agent-c run 287: the `if (arg3) {} if (1) {}` pair after this call dropped (stale: removal sweep, instruction stream identical at 99.00); agent-c run 263: code-free test + BB split after the loader call (kit CCC random search): 98.25 -> 98.33; run 268 re-tune: `if (arg3) {}` */
    w = arg4; /* run 268 re-tune: the agent-g run 210 folded use dropped */
    x = (f32)arg1 + (-((f32)w / 2) * arg5);
    fw = w * arg5;
    y = (f32)arg2 + (-((f32)h / 2) * arg6);
    fh = h * arg6;
    /* agent-g run 293: the RDPHALF_1 packet back on nD() (the run-255 nR1 is inert: byte-identical) */
    /* agent-g run 295: the dsdx term reads the parameter, `arg4 - 1` (w == arg4 here: w is set from arg4 above and
     * never reassigned), so w's last use is fw and its reload no longer outlives the rect pointer: w-reload t3 /
     * rect pointer t2 like the target (w / arg4 use-substitution grid, 47): 99.004 -> 99.141 */
    /* agent-g run 300 (EXACT): the rectangle packet pointer is the spr variable reused (spr is dead after the
     * loader call; the Gfx * round-trips through the cast). One variable = one uopt live range over both
     * values, so spr's range spans the rectangle blocks too: lower priority, it colours after the texture
     * append's dl / n (v0 / v1) and _g (t0) and lands in t1 as the target (99.922 -> 100). */
    spr = (Spr *)me(me(CTX))->nD();
    gSPScisTextureRectangle((Gfx *)spr, me(me(CTX))->nD(), me(CTX)->nD(), x << 2, y << 2, (x + (s32)fw) << 2, (y + (s32)fh) << 2, 0, 0, 0,
        (s32)(((f32)(arg4 - 1) * 1024.0f) / fw), (s32)(((f32)(h - 1) * 1024.0f) / fh));
